WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_boat_round'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '往返流水', 'kp-trv-boat-round', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "往返流水"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "去的时候顺水，回来的时候必然逆水。总距离是单程的 2 倍。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“一艘船在两港之间往返一次，总共用了 10 小时……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这实际上就是“不等距离往返”（因为去回速度不同，耗时不同）的变形。"}]}, {"type": "katexBlock", "attrs": {"content": "T_{往返总} = \\frac{S}{V_{船} + V_{水}} + \\frac{S}{V_{船} - V_{水}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记水流反转：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "有些题目故意不写“返回时逆水”，而是说“原路返回”。如果去程是顺风/顺水，回程不用想绝对是逆风/逆水，速度必须变！切勿用同一个速度算全程。"}]}]}]}$$ AS jsonb), NULL, '往返流水的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "往返流水"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_boat_round", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
